'use strict';
/* Мурчат — сервер. Один файл, без зависимостей: нужен только Node.js 18 или новее.
   Внутри: общая логика, всё приложение (страницы, скрипты, картинки) и веб-сервер.
   Запуск: node server.js   Переменные: PORT (по умолчанию 3000), DATA_DIR (где хранить данные). */
const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const zlib = require('zlib');

// ===== общая логика (одна и та же в демо и на сервере) =====
const MurchatCore = (() => {
  const module = { exports: {} };
/* Мурчат — общая логика.
   Один и тот же код работает на сервере (Node.js) и в демо-версии внутри браузера. */
(function (root, factory) {
  if (typeof module === 'object' && module.exports) module.exports = factory();
  else root.MurchatCore = factory();
})(typeof self !== 'undefined' ? self : this, function () {
  'use strict';

  const PHOTOS = ['c1', 'c2', 'c3', 'c4'];
  const LIMITS = { name: 20, bio: 70, group: 24, desc: 100, text: 300 };
  const EMOJI = ['❤️', '😺', '🐾', '✨', '😂'];
  const PATTERNS = ['none', 'paws', 'dots', 'waves'];
  const LETTERS_RE = /^[ТЫФЬ ]+$/; // Т Ы Ф Ь и пробел
  const NAME_RE = /^[a-z0-9_]{3,20}$/;
  const HEX_RE = /^#[0-9a-fA-F]{6}$/;
  const BANNERS = ['#ff8fb1', '#ffb38a', '#ffd66b', '#a5d6a7', '#8fd9c0', '#8ec5ff', '#c7a6ff', '#f48fb1'];
  const CTRL_RE = /[\u0000-\u001f\u007f-\u009f​-‏‪-‮⁦-⁩﻿]/g;
  const MAX_MEMBERS = 50;

  const len = (s) => Array.from(s).length;
  const clean = (s) => String(s == null ? '' : s).replace(CTRL_RE, '').replace(/\s+/g, ' ').trim();
  const norm = (s) => clean(s).replace(/^@/, '').toLowerCase();
  const ok = (data) => ({ status: 200, data: data === undefined ? { ok: true } : data });
  const err = (status, error) => ({ status, data: { error } });

  function createCore(opts) {
    const db = opts.db;
    const save = opts.save || function () {};
    const hashPassword = opts.hashPassword;
    const randomHex = opts.randomHex;
    const now = opts.now || Date.now;
    const push = opts.push || function () {};
    const rateLimit = opts.rateLimit !== false;
    const isOnline = opts.isOnline || function (name) {
      const u = db.users[name];
      return !!u && now() - (u.seen || 0) < 30000;
    };

    // ---------- подготовка базы (и перенос со старой версии) ----------
    db.users = db.users || {};
    db.sessions = db.sessions || {};
    db.messages = db.messages || [];
    db.reads = db.reads || {};
    db.groups = db.groups || {};
    db.nextId = db.nextId || 1;
    db.nextGid = db.nextGid || 1;
    if (!db.version) {
      for (const me of Object.keys(db.reads)) {
        const r = db.reads[me];
        for (const k of Object.keys(r)) {
          if (k.indexOf(':') < 0) { r['u:' + k] = r[k]; delete r[k]; }
        }
      }
      db.version = 2;
    }

    // ---------- ограничение частоты входа ----------
    const hits = new Map();
    function tooMany(ip) {
      if (!rateLimit) return false;
      const t = now();
      const arr = (hits.get(ip) || []).filter((x) => t - x < 10 * 60 * 1000);
      arr.push(t);
      hits.set(ip, arr);
      return arr.length > 40;
    }

    // ---------- представления ----------
    function defBanner(name) {
      let h = 0;
      for (const c of name) h = (h * 31 + c.charCodeAt(0)) >>> 0;
      return BANNERS[h % BANNERS.length];
    }
    function presenceOf(name, viewer) {
      const u = db.users[name];
      if (!u) return { online: false, seen: null, hidden: true };
      const hide = u.showOnline === false && viewer !== name;
      if (hide) return { online: false, seen: null, hidden: true };
      return { online: !!isOnline(name), seen: u.seen || null, hidden: false };
    }
    function pubUser(name, viewer) {
      const u = db.users[name];
      if (!u) return { username: name, name: name, avatar: null, banner: '#b0bec5', pattern: 'none', bio: '', joined: 0, online: false, seen: null, hidden: true, gone: true };
      const p = presenceOf(name, viewer);
      return {
        username: name, name: u.name || name, avatar: u.avatar || null,
        banner: u.banner || defBanner(name), pattern: u.pattern || 'paws', bio: u.bio || '',
        bot: !!u.bot, joined: u.created || 0, online: p.online, seen: p.seen, hidden: p.hidden,
      };
    }
    function selfUser(name) {
      const u = db.users[name];
      return Object.assign(pubUser(name, name), { showOnline: u.showOnline !== false, readReceipts: u.readReceipts !== false });
    }
    function pubGroup(g) {
      return { id: g.id, name: g.name, avatar: g.avatar || null, desc: g.desc || '', owner: g.owner, members: g.members.length, created: g.created };
    }
    const isMember = (g, name) => !!g && g.members.indexOf(name) >= 0;

    function participants(m) {
      if (m.gid) { const g = db.groups[m.gid]; return g ? g.members.slice() : []; }
      return m.from === m.to ? [m.from] : [m.from, m.to];
    }
    const visibleTo = (m, me) => participants(m).indexOf(me) >= 0;
    function deliver(m, ev) { participants(m).forEach((u) => push(u, ev)); }
    function chatKey(m, me) {
      if (m.gid) return 'g:' + m.gid;
      return 'u:' + (m.from === me ? m.to : m.from);
    }

    // ---------- аккаунты ----------
    function cleanName(raw, fallback) {
      const n = clean(raw);
      if (!n) return fallback;
      return n;
    }
    async function register(b, ip) {
      if (tooMany(ip || 'x')) return err(429, 'Слишком много попыток, подожди немного');
      const name = norm(b.username);
      const pass = String(b.password || '');
      if (!NAME_RE.test(name)) return err(400, 'Юзернейм: 3–20 символов, латиница, цифры и _');
      if (pass.length < 4 || pass.length > 64) return err(400, 'Пароль: от 4 до 64 символов');
      if (db.users[name]) return err(409, 'Такой юзернейм уже занят');
      const shown = cleanName(b.name, name);
      if (len(shown) > LIMITS.name) return err(400, 'Имя слишком длинное: максимум ' + LIMITS.name + ' символов');
      const salt = randomHex(16);
      db.users[name] = { salt, hash: await hashPassword(pass, salt), name: shown, avatar: null, bio: '', created: now(), seen: now() };
      const token = addSession(name);
      save();
      return ok({ token, me: selfUser(name) });
    }
    async function login(b, ip) {
      if (tooMany(ip || 'x')) return err(429, 'Слишком много попыток, подожди немного');
      const name = norm(b.username);
      const u = db.users[name];
      if (!u || u.bot || (await hashPassword(String(b.password || ''), u.salt)) !== u.hash) return err(401, 'Неверный юзернейм или пароль');
      const token = addSession(name);
      u.seen = now();
      save();
      return ok({ token, me: selfUser(name) });
    }
    function addSession(name) {
      const token = randomHex(32);
      db.sessions[token] = name;
      const mine = Object.keys(db.sessions).filter((t) => db.sessions[t] === name);
      while (mine.length > 10) delete db.sessions[mine.shift()];
      return token;
    }
    function auth(token) {
      const n = token && db.sessions[token];
      return n && db.users[n] ? n : null;
    }
    function touch(name) { if (db.users[name]) db.users[name].seen = now(); }

    // ---------- профиль ----------
    function updateMe(me, b) {
      const u = db.users[me];
      if ('name' in b) {
        const n = clean(b.name);
        if (!n) return err(400, 'Имя не должно быть пустым');
        if (len(n) > LIMITS.name) return err(400, 'Имя слишком длинное: максимум ' + LIMITS.name + ' символов');
        u.name = n;
      }
      if ('bio' in b) {
        const s = clean(b.bio);
        if (len(s) > LIMITS.bio) return err(400, 'О себе: максимум ' + LIMITS.bio + ' символов');
        u.bio = s;
      }
      if ('avatar' in b) {
        if (b.avatar !== null && PHOTOS.indexOf(b.avatar) < 0) return err(400, 'Нет такой фотографии');
        u.avatar = b.avatar;
      }
      if ('banner' in b) {
        if (!HEX_RE.test(String(b.banner))) return err(400, 'Неверный цвет баннера');
        u.banner = String(b.banner).toLowerCase();
      }
      if ('pattern' in b) {
        if (PATTERNS.indexOf(b.pattern) < 0) return err(400, 'Нет такого узора');
        u.pattern = b.pattern;
      }
      if ('showOnline' in b) u.showOnline = !!b.showOnline;
      if ('readReceipts' in b) u.readReceipts = !!b.readReceipts;
      save();
      return ok(selfUser(me));
    }
    async function changePassword(me, token, b) {
      const u = db.users[me];
      if ((await hashPassword(String(b.old || ''), u.salt)) !== u.hash) return err(400, 'Старый пароль неверный');
      const next = String(b.next || '');
      if (next.length < 4 || next.length > 64) return err(400, 'Новый пароль: от 4 до 64 символов');
      u.salt = randomHex(16);
      u.hash = await hashPassword(next, u.salt);
      for (const t of Object.keys(db.sessions)) if (db.sessions[t] === me && t !== token) delete db.sessions[t];
      save();
      return ok();
    }

    function searchUsers(me, q) {
      q = norm(q);
      if (!q) return [];
      const out = [];
      for (const n of Object.keys(db.users)) {
        if (n === me) continue;
        const dn = String(db.users[n].name || n).toLowerCase();
        if (n.indexOf(q) < 0 && dn.indexOf(q) < 0) continue;
        out.push({ n, rank: n === q || dn === q ? 0 : n.indexOf(q) === 0 || dn.indexOf(q) === 0 ? 1 : 2 });
      }
      out.sort((a, b) => a.rank - b.rank || a.n.localeCompare(b.n));
      return out.slice(0, 20).map((o) => pubUser(o.n, me));
    }

    function profile(me, name) {
      if (!db.users[name]) return err(404, 'Нет такого пользователя');
      const common = name === me ? [] : Object.values(db.groups)
        .filter((g) => isMember(g, me) && isMember(g, name)).map(pubGroup);
      const media = [];
      for (let i = db.messages.length - 1; i >= 0 && media.length < 30; i--) {
        const m = db.messages[i];
        if (!m.photo || m.gid) continue;
        const inThread = name === me ? (m.from === me && m.to === me) : ((m.from === me && m.to === name) || (m.from === name && m.to === me));
        if (inThread) media.push({ id: m.id, photo: m.photo, ts: m.ts, from: m.from });
      }
      let count = 0;
      for (const m of db.messages) {
        if (m.gid || m.sys) continue;
        if (name === me ? (m.from === me && m.to === me) : ((m.from === me && m.to === name) || (m.from === name && m.to === me))) count++;
      }
      return ok({ user: pubUser(name, me), common, media, count });
    }

    // ---------- чаты и сообщения ----------
    function chats(me) {
      const map = new Map();
      const mine = new Set(Object.values(db.groups).filter((g) => isMember(g, me)).map((g) => g.id));
      const rd = db.reads[me] || {};
      for (const m of db.messages) {
        let c;
        if (m.gid) {
          if (!mine.has(m.gid)) continue;
          const key = 'g:' + m.gid;
          c = map.get(key) || { kind: 'group', id: m.gid, key, unread: 0, last: null };
          map.set(key, c);
        } else {
          if (m.from !== me && m.to !== me) continue;
          const other = m.from === me ? m.to : m.from;
          const key = 'u:' + other;
          c = map.get(key) || { kind: 'user', id: other, key, unread: 0, last: null };
          map.set(key, c);
        }
        c.last = m;
        if (!m.sys && m.from !== me && m.id > (rd[c.key] || 0)) c.unread++;
      }
      return Array.from(map.values()).sort((a, b) => b.last.id - a.last.id).map((c) => {
        if (c.kind === 'user') c.user = pubUser(c.id, me);
        else c.group = pubGroup(db.groups[c.id]);
        return c;
      });
    }

    function thread(me, kind, id) {
      if (kind === 'user') {
        if (!db.users[id]) return err(404, 'Нет такого пользователя');
        const msgs = db.messages.filter((m) => !m.gid && ((m.from === me && m.to === id) || (m.from === id && m.to === me)));
        let peerRead = null;
        if (id !== me && db.users[id].readReceipts !== false) peerRead = ((db.reads[id] || {})['u:' + me]) || 0;
        return ok({ kind, user: pubUser(id, me), messages: msgs.slice(-300), peerRead });
      }
      const g = db.groups[id];
      if (!g || !isMember(g, me)) return err(404, 'Нет такой группы');
      const msgs = db.messages.filter((m) => m.gid === id);
      return ok({ kind, group: pubGroup(g), members: g.members.map((n) => pubUser(n, me)), messages: msgs.slice(-300) });
    }

    function send(me, b) {
      const text = String(b.text || '').toUpperCase().trim();
      const photo = b.photo || null;
      if (text && (!LETTERS_RE.test(text) || text.length > LIMITS.text)) return err(400, 'Можно только буквы Т, Ы, Ф, Ь и пробел');
      if (photo && PHOTOS.indexOf(photo) < 0) return err(400, 'Нет такой фотографии');
      if (!text && !photo) return err(400, 'Пустое сообщение');
      const msg = { id: 0, from: me, text, photo, ts: now() };
      if (b.gid != null && b.gid !== '') {
        const g = db.groups[Number(b.gid)];
        if (!g || !isMember(g, me)) return err(404, 'Нет такой группы');
        msg.gid = g.id;
      } else {
        const to = norm(b.to);
        if (!db.users[to]) return err(404, 'Нет такого пользователя');
        msg.to = to;
      }
      if (b.reply != null && b.reply !== '') {
        const rm = db.messages.find((x) => x.id === Number(b.reply));
        if (rm && !rm.sys && visibleTo(rm, me) && (msg.gid ? rm.gid === msg.gid : (!rm.gid && ((rm.from === me && rm.to === msg.to) || (rm.from === msg.to && rm.to === me))))) {
          msg.reply = { id: rm.id, from: rm.from, text: String(rm.text || '').slice(0, 60), photo: !!rm.photo };
        }
      }
      msg.id = db.nextId++;
      db.messages.push(msg);
      save();
      deliver(msg, { type: 'message', message: msg });
      return ok(msg);
    }

    function sysMessage(gid, from, sys, arg) {
      const m = { id: db.nextId++, gid, from, sys, arg: arg == null ? '' : String(arg), text: '', photo: null, ts: now() };
      db.messages.push(m);
      deliver(m, { type: 'message', message: m });
      return m;
    }

    function deleteMessage(me, id) {
      const i = db.messages.findIndex((m) => m.id === id);
      if (i < 0) return err(404, 'Сообщение не найдено');
      const m = db.messages[i];
      if (m.sys || m.from !== me) return err(403, 'Можно удалять только свои сообщения');
      const who = participants(m);
      db.messages.splice(i, 1);
      save();
      who.forEach((u) => push(u, { type: 'delete', id, gid: m.gid || null, from: m.from, to: m.to || null }));
      return ok();
    }

    function react(me, id, emoji) {
      const m = db.messages.find((x) => x.id === id);
      if (!m || m.sys || !visibleTo(m, me)) return err(404, 'Сообщение не найдено');
      if (emoji) {
        if (EMOJI.indexOf(emoji) < 0) return err(400, 'Такой реакции нет');
        m.r = m.r || {};
        m.r[me] = emoji;
      } else if (m.r) {
        delete m.r[me];
        if (!Object.keys(m.r).length) delete m.r;
      }
      save();
      deliver(m, { type: 'update', message: m });
      return ok(m);
    }

    function markRead(me, kind, id) {
      let upTo = 0;
      let key;
      if (kind === 'user') {
        key = 'u:' + id;
        for (const m of db.messages) if (!m.gid && m.from === id && m.to === me && m.id > upTo) upTo = m.id;
      } else {
        const g = db.groups[id];
        if (!g || !isMember(g, me)) return err(404, 'Нет такой группы');
        key = 'g:' + id;
        for (const m of db.messages) if (m.gid === id && m.id > upTo) upTo = m.id;
      }
      db.reads[me] = db.reads[me] || {};
      db.reads[me][key] = upTo;
      save();
      if (kind === 'user' && id !== me && db.users[id] && db.users[me].readReceipts !== false) push(id, { type: 'read', by: me, upTo });
      return ok();
    }

    function typing(me, b) {
      if (b.gid != null && b.gid !== '') {
        const g = db.groups[Number(b.gid)];
        if (!g || !isMember(g, me)) return ok();
        g.members.forEach((u) => { if (u !== me) push(u, { type: 'typing', from: me, gid: g.id }); });
      } else {
        const to = norm(b.to);
        if (to && to !== me && db.users[to]) push(to, { type: 'typing', from: me });
      }
      return ok();
    }

    // ---------- группы ----------
    function notifyGroup(g, extra) {
      g.members.concat(extra || []).forEach((u) => push(u, { type: 'group', gid: g.id }));
    }
    function createGroup(me, b) {
      const name = clean(b.name);
      if (!name) return err(400, 'Назови группу');
      if (len(name) > LIMITS.group) return err(400, 'Название группы: максимум ' + LIMITS.group + ' символов');
      const desc = clean(b.desc);
      if (len(desc) > LIMITS.desc) return err(400, 'Описание: максимум ' + LIMITS.desc + ' символов');
      const avatar = b.avatar || null;
      if (avatar && PHOTOS.indexOf(avatar) < 0) return err(400, 'Нет такой фотографии');
      const list = [];
      (Array.isArray(b.members) ? b.members : []).forEach((x) => {
        const n = norm(x);
        if (n && n !== me && db.users[n] && list.indexOf(n) < 0) list.push(n);
      });
      if (!list.length) return err(400, 'Добавь хотя бы одного участника');
      if (list.length + 1 > MAX_MEMBERS) return err(400, 'В группе может быть не больше ' + MAX_MEMBERS + ' участников');
      const g = { id: db.nextGid++, name, avatar, desc, owner: me, members: [me].concat(list), created: now() };
      db.groups[g.id] = g;
      sysMessage(g.id, me, 'created', name);
      save();
      notifyGroup(g);
      return ok({ group: pubGroup(g) });
    }
    function groupInfo(me, id) {
      const g = db.groups[id];
      if (!g || !isMember(g, me)) return err(404, 'Нет такой группы');
      return ok({
        group: pubGroup(g),
        members: g.members.map((n) => Object.assign(pubUser(n, me), { owner: n === g.owner })),
      });
    }
    function updateGroup(me, id, b) {
      const g = db.groups[id];
      if (!g || !isMember(g, me)) return err(404, 'Нет такой группы');
      if (g.owner !== me) return err(403, 'Это может делать только владелец группы');
      let renamed = false;
      if ('name' in b) {
        const n = clean(b.name);
        if (!n) return err(400, 'Назови группу');
        if (len(n) > LIMITS.group) return err(400, 'Название группы: максимум ' + LIMITS.group + ' символов');
        if (n !== g.name) { g.name = n; renamed = true; }
      }
      if ('desc' in b) {
        const d = clean(b.desc);
        if (len(d) > LIMITS.desc) return err(400, 'Описание: максимум ' + LIMITS.desc + ' символов');
        g.desc = d;
      }
      if ('avatar' in b) {
        if (b.avatar !== null && PHOTOS.indexOf(b.avatar) < 0) return err(400, 'Нет такой фотографии');
        g.avatar = b.avatar;
      }
      if (renamed) sysMessage(g.id, me, 'renamed', g.name);
      save();
      notifyGroup(g);
      return ok({ group: pubGroup(g) });
    }
    function addMembers(me, id, b) {
      const g = db.groups[id];
      if (!g || !isMember(g, me)) return err(404, 'Нет такой группы');
      if (g.owner !== me) return err(403, 'Это может делать только владелец группы');
      const added = [];
      (Array.isArray(b.add) ? b.add : []).forEach((x) => {
        const n = norm(x);
        if (n && db.users[n] && !isMember(g, n) && added.indexOf(n) < 0) added.push(n);
      });
      if (!added.length) return err(400, 'Некого добавлять');
      if (g.members.length + added.length > MAX_MEMBERS) return err(400, 'В группе может быть не больше ' + MAX_MEMBERS + ' участников');
      added.forEach((n) => { g.members.push(n); sysMessage(g.id, me, 'added', n); });
      save();
      notifyGroup(g);
      return ok(groupInfo(me, id).data);
    }
    function kick(me, id, b) {
      const g = db.groups[id];
      if (!g || !isMember(g, me)) return err(404, 'Нет такой группы');
      if (g.owner !== me) return err(403, 'Это может делать только владелец группы');
      const n = norm(b.username);
      if (n === me || !isMember(g, n)) return err(400, 'Нельзя убрать этого участника');
      sysMessage(g.id, me, 'kicked', n);
      g.members = g.members.filter((x) => x !== n);
      save();
      notifyGroup(g, [n]);
      return ok(groupInfo(me, id).data);
    }
    function leave(me, id) {
      const g = db.groups[id];
      if (!g || !isMember(g, me)) return err(404, 'Нет такой группы');
      sysMessage(g.id, me, 'left', me);
      const everyone = g.members.slice();
      g.members = g.members.filter((x) => x !== me);
      if (!g.members.length) {
        delete db.groups[g.id];
        db.messages = db.messages.filter((m) => m.gid !== g.id);
      } else if (g.owner === me) {
        g.owner = g.members[0];
      }
      save();
      everyone.forEach((u) => push(u, { type: 'group', gid: g.id }));
      return ok();
    }

    // ---------- статистика ----------
    function stats(me) {
      const mine = new Set(Object.values(db.groups).filter((g) => isMember(g, me)).map((g) => g.id));
      const letters = { 'Т': 0, 'Ы': 0, 'Ф': 0, 'Ь': 0 };
      let sent = 0; let received = 0; let spaces = 0; let photos = 0; let reactions = 0; let first = 0;
      const partners = new Set();
      for (const m of db.messages) {
        if (m.sys) continue;
        const dm = !m.gid && (m.from === me || m.to === me);
        const grp = m.gid && mine.has(m.gid);
        if (!dm && !grp) continue;
        if (m.from === me) {
          sent++;
          if (!first || m.ts < first) first = m.ts;
          if (m.photo) photos++;
          if (m.r) reactions += Object.keys(m.r).length;
          for (const ch of m.text || '') { if (ch === ' ') spaces++; else if (letters[ch] !== undefined) letters[ch]++; }
        } else received++;
        if (dm) partners.add(m.from === me ? m.to : m.from);
      }
      return ok({ sent, received, letters, spaces, photos, reactions, first, chats: partners.size, groups: mine.size });
    }

    // ---------- маршрутизатор ----------
    async function handle(req) {
      const method = req.method || 'GET';
      const full = String(req.path || '/');
      const qi = full.indexOf('?');
      const p = qi < 0 ? full : full.slice(0, qi);
      const params = new URLSearchParams(qi < 0 ? '' : full.slice(qi + 1));
      const b = req.body && typeof req.body === 'object' ? req.body : {};
      if (p === '/register' && method === 'POST') return register(b, req.ip);
      if (p === '/login' && method === 'POST') return login(b, req.ip);
      const me = auth(req.token);
      if (!me) return err(401, 'Нужно войти');
      touch(me);
      let m;
      if (p === '/ping') return ok();
      if (p === '/me' && method === 'GET') return ok(selfUser(me));
      if (p === '/me' && method === 'PUT') return updateMe(me, b);
      if (p === '/logout' && method === 'POST') { delete db.sessions[req.token]; save(); return ok(); }
      if (p === '/password' && method === 'POST') return changePassword(me, req.token, b);
      if (p === '/users' && method === 'GET') return ok(searchUsers(me, params.get('q')));
      if ((m = p.match(/^\/users\/([a-z0-9_]+)$/)) && method === 'GET') return profile(me, m[1]);
      if (p === '/chats' && method === 'GET') return ok(chats(me));
      if (p === '/stats' && method === 'GET') return stats(me);
      if ((m = p.match(/^\/messages\/u\/([a-z0-9_]+)$/)) && method === 'GET') return thread(me, 'user', m[1]);
      if ((m = p.match(/^\/messages\/g\/(\d+)$/)) && method === 'GET') return thread(me, 'group', Number(m[1]));
      if (p === '/messages' && method === 'POST') return send(me, b);
      if ((m = p.match(/^\/messages\/(\d+)$/)) && method === 'DELETE') return deleteMessage(me, Number(m[1]));
      if ((m = p.match(/^\/messages\/(\d+)\/react$/)) && method === 'POST') return react(me, Number(m[1]), b.emoji);
      if ((m = p.match(/^\/read\/u\/([a-z0-9_]+)$/)) && method === 'POST') return markRead(me, 'user', m[1]);
      if ((m = p.match(/^\/read\/g\/(\d+)$/)) && method === 'POST') return markRead(me, 'group', Number(m[1]));
      if (p === '/typing' && method === 'POST') return typing(me, b);
      if (p === '/groups' && method === 'POST') return createGroup(me, b);
      if ((m = p.match(/^\/groups\/(\d+)$/)) && method === 'GET') return groupInfo(me, Number(m[1]));
      if ((m = p.match(/^\/groups\/(\d+)$/)) && method === 'PUT') return updateGroup(me, Number(m[1]), b);
      if ((m = p.match(/^\/groups\/(\d+)\/members$/)) && method === 'POST') return addMembers(me, Number(m[1]), b);
      if ((m = p.match(/^\/groups\/(\d+)\/kick$/)) && method === 'POST') return kick(me, Number(m[1]), b);
      if ((m = p.match(/^\/groups\/(\d+)\/leave$/)) && method === 'POST') return leave(me, Number(m[1]));
      return err(404, 'Не найдено');
    }

    return {
      handle, auth, touch, presenceOf,
      // для ботов демо-версии
      send, markRead, typing,
      db,
    };
  }

  return { createCore, PHOTOS, LIMITS, EMOJI, PATTERNS, BANNERS };
});

  return module.exports;
})();

// ===== настройки и база =====
const PORT = Number(process.env.PORT) || 3000;
const DATA_DIR = process.env.DATA_DIR || path.join(__dirname, 'data');
const DB_FILE = path.join(DATA_DIR, 'db.json');
try { fs.mkdirSync(DATA_DIR, { recursive: true }); } catch (e) { /* ignore */ }
let db = {};
try { db = JSON.parse(fs.readFileSync(DB_FILE, 'utf8')); } catch (e) { db = {}; }

let saveTimer = null;
function save() {
  if (saveTimer) return;
  saveTimer = setTimeout(() => {
    saveTimer = null;
    const tmp = DB_FILE + '.tmp';
    fs.writeFile(tmp, JSON.stringify(db), (err) => { if (!err) fs.rename(tmp, DB_FILE, () => {}); });
  }, 400);
}
function flush() {
  try { fs.writeFileSync(DB_FILE + '.tmp', JSON.stringify(db)); fs.renameSync(DB_FILE + '.tmp', DB_FILE); } catch (e) { /* ignore */ }
}
['SIGTERM', 'SIGINT'].forEach((sig) => process.on(sig, () => { flush(); process.exit(0); }));

// ===== события в реальном времени (SSE) =====
const clients = new Map(); // username -> Set(res)
function sendEvent(res, ev) { try { res.write('data: ' + JSON.stringify(ev) + '\n\n'); } catch (e) { /* ignore */ } }
function push(name, ev) {
  const set = clients.get(name);
  if (set) set.forEach((r) => sendEvent(r, ev));
}
function broadcastPresence(name, online) {
  const u = db.users[name];
  if (!u || u.showOnline === false) return;
  const ev = { type: 'presence', user: name, online, seen: u.seen || Date.now() };
  clients.forEach((set) => set.forEach((r) => sendEvent(r, ev)));
}
setInterval(() => clients.forEach((set) => set.forEach((r) => { try { r.write(': ping\n\n'); } catch (e) { /* ignore */ } })), 25000);

const core = MurchatCore.createCore({
  db, save, push,
  hashPassword: (p, s) => new Promise((resolve, reject) => crypto.scrypt(p, s, 32, (e, k) => (e ? reject(e) : resolve(k.toString('hex'))))),
  randomHex: (n) => crypto.randomBytes(n).toString('hex'),
  isOnline: (name) => clients.has(name) || (!!db.users[name] && Date.now() - (db.users[name].seen || 0) < 30000),
});

// ===== приложение: файлы встроены прямо сюда =====
const FILES = {"/index.html": ["text/html; charset=utf-8", ""], "/style.css": ["text/css; charset=utf-8", ""], "/app.js": ["text/javascript; charset=utf-8", ""], "/sw.js": ["text/javascript; charset=utf-8", ""], "/manifest.webmanifest": ["application/manifest+json", ""], "/hero.webp": ["image/webp", ""], "/cats/c1.jpg": ["image/jpeg", ""], "/cats/c1-t.jpg": ["image/jpeg", ""], "/cats/c2.jpg": ["image/jpeg", ""], "/cats/c2-t.jpg": ["image/jpeg", ""], "/cats/c3.jpg": ["image/jpeg", ""], "/cats/c3-t.jpg": ["image/jpeg", ""], "/cats/c4.jpg": ["image/jpeg", ""], "/cats/c4-t.jpg": ["image/jpeg", ""], "/icons/icon-192.png": ["image/png", ""], "/icons/icon-512.png": ["image/png", ""], "/icons/maskable-512.png": ["image/png", ""], "/icons/apple-touch-icon.png": ["image/png", ""], "/icons/favicon.png": ["image/png", ""]};
const STATIC = new Map();
for (const [url, [type, b64]] of Object.entries(FILES)) {
  const data = Buffer.from(b64, 'base64');
  const text = /^(text|application\/(json|manifest|javascript))/.test(type);
  STATIC.set(url, {
    type, data, text,
    gz: text ? zlib.gzipSync(data, { level: 9 }) : null,
    etag: '"' + crypto.createHash('sha1').update(data).digest('hex').slice(0, 16) + '"',
  });
}
STATIC.set('/', STATIC.get('/index.html'));

const HEADERS = {
  'X-Content-Type-Options': 'nosniff',
  'Referrer-Policy': 'no-referrer',
  'X-Frame-Options': 'DENY',
  'Content-Security-Policy': "default-src 'self'; img-src 'self' data:; style-src 'self' 'unsafe-inline'; script-src 'self'; connect-src 'self'; worker-src 'self'; manifest-src 'self'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'",
};

function serveStatic(req, res, url) {
  const f = STATIC.get(decodeURIComponent(url.pathname));
  if (!f || (req.method !== 'GET' && req.method !== 'HEAD')) {
    res.writeHead(404, Object.assign({ 'Content-Type': 'text/plain; charset=utf-8' }, HEADERS));
    return res.end('Не найдено');
  }
  const headers = Object.assign({ 'Content-Type': f.type, ETag: f.etag, Vary: 'Accept-Encoding' }, HEADERS);
  headers['Cache-Control'] = f.text ? 'no-cache' : 'public, max-age=604800';
  if (req.headers['if-none-match'] === f.etag) { res.writeHead(304, headers); return res.end(); }
  let body = f.data;
  if (f.gz && /\bgzip\b/.test(req.headers['accept-encoding'] || '')) { headers['Content-Encoding'] = 'gzip'; body = f.gz; }
  headers['Content-Length'] = body.length;
  res.writeHead(200, headers);
  res.end(req.method === 'HEAD' ? undefined : body);
}

function sendJson(res, code, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(code, Object.assign({ 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' }, HEADERS));
  res.end(body);
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    req.on('data', (c) => { data += c; if (data.length > 20000) { reject(new Error('big')); req.destroy(); } });
    req.on('end', () => { try { resolve(data ? JSON.parse(data) : {}); } catch (e) { reject(e); } });
    req.on('error', reject);
  });
}

function sse(req, res, url) {
  const token = url.searchParams.get('token') || '';
  const me = core.auth(token);
  if (!me) return sendJson(res, 401, { error: 'Нужно войти' });
  res.writeHead(200, Object.assign({ 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache', Connection: 'keep-alive', 'X-Accel-Buffering': 'no' }, HEADERS));
  res.write('retry: 3000\n\n');
  const first = !clients.has(me);
  if (first) clients.set(me, new Set());
  clients.get(me).add(res);
  core.touch(me);
  if (first) broadcastPresence(me, true);
  req.on('close', () => {
    const set = clients.get(me);
    if (!set) return;
    set.delete(res);
    if (!set.size) {
      clients.delete(me);
      core.touch(me);
      save();
      broadcastPresence(me, false);
    }
  });
}

async function api(req, res, url) {
  let body = {};
  if (req.method === 'POST' || req.method === 'PUT' || req.method === 'DELETE') body = await readBody(req);
  const token = (req.headers.authorization || '').replace(/^Bearer /, '');
  const ip = String(req.headers['x-forwarded-for'] || req.socket.remoteAddress || '').split(',')[0].trim();
  const r = await core.handle({ method: req.method, path: url.pathname.slice(4) + url.search, body, token, ip });
  sendJson(res, r.status, r.data);
}

const server = http.createServer(async (req, res) => {
  let url;
  try { url = new URL(req.url, 'http://x'); } catch (e) { res.writeHead(400); return res.end(); }
  try {
    if (url.pathname === '/api/events') return sse(req, res, url);
    if (url.pathname.startsWith('/api/')) return await api(req, res, url);
    return serveStatic(req, res, url);
  } catch (e) {
    if (!res.headersSent) sendJson(res, 400, { error: 'Плохой запрос' }); else res.end();
  }
});
server.listen(PORT, () => console.log('Мурчат запущен: http://localhost:' + PORT));
